sketches.source:
setcpm(60/4)

// Rain on the leaves above you
rain: s("rain").slow(4).intensity(.5).elevation(40).distance(3).gain(.26)

// A fine mist: unrelated pink noise in each ear, wide and all around
mist: s("pink").slow(8).icorr(.1).hpf(3000).lpf(8000).gain(.025)

// Drops falling from the canopy at random points around your head
drips: s("drip*8?0.5").azimuth(rand.range(-180, 180)).elevation(rand.range(0, 60))
  .distance(rand.range(1, 4)).seed("canopy").gain(.18)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("<d2 d2 bb1 c2>").slow(2).s("sine").binaural(2)
  .attack(3).sustain(1).release(4).gain(.24)

// A soft pad: Dm, Bb, Gm, A
pad: note("<[d3,a3,f4] [bb2,f3,d4] [g2,d3,bb3] [a2,e3,c#4]>").slow(2)
  .s("sawtooth").unison(3).detune(.2).lpf(900)
  .attack(2).release(3).room(.7).gain(.12)

setcpm(72/4)

// A brook running past you from left to right every eight bars
brook: s("stream").slow(4).azimuth(saw.range(-120, 120).slow(8)).distance(2).posglide(.5).gain(.24)
breeze: s("wind").slow(8).intensity(.2).gain(.07)

// A wren on the far bank, a thrush behind you
wren: s("bird").slow(3).azimuth(70).distance(5).gain(.24)
thrush: s("bird").slow(5).azimuth(-150).elevation(20).distance(6).gain(.18)

// Stepping stones: under about 0.7 ms, a delay between the ears moves the pluck sideways
stones: n("0 2 4 7 4 2 0 ~").scale("G:major pentatonic").transpose(12)
  .s("triangle").timbre("bright").itd(sine.range(-.6, .6).slow(4))
  .decay(.3).sustain(0).release(.4).room(.4).gain(.2)

// A soft centred bass, with no delay at all: G, Em, C, D
bass: note("<g2 e2 c2 d2>").s("sine").attack(.2).sustain(.7).release(.8).gain(.28)

setcpm(56/4)

// Crickets in the grass on both sides
grass: s("insect").slow(4).azimuth(-100).distance(4).gain(.08)
field: s("insect").slow(4).azimuth(110).distance(6).gain(.07)

// Close chirps: ild makes the right ear louder; earswap flips the steps marked 1 to the left
chirps: s("click*8?0.5").hpf(4000).ild(9).earswap("0 1 1 0 1 0 0 1").seed("meadow").gain(.08)

// Frogs at the pond behind you, and an owl far off to the left
frogs: s("click*4?0.4").lpf(1200).azimuth(170).distance(5).seed("pond").gain(.1)
owl: note("<~ [~ ~ a3 [a3 e3]] ~ ~>").s("hum").azimuth(-70).distance(8)
  .attack(.05).release(.5).gain(.12)

// A 4 Hz binaural beat in the theta range: keep the volume low
drone: note("<a1 a1 f1 g1>").slow(2).s("sine").binaural(4)
  .attack(3).sustain(1).release(4).gain(.22)

// Slow choir chords under the stars: Am, F, Dm, E
choir: note("<[a2,e3,c4] [f2,c3,a3] [d3,f3,a3] [e2,b2,g#3]>").slow(2)
  .s("choir").syl("<oo ah oo oh>").attack(3).release(4).space("hall").gain(.18)

setcpm(48/4)

// The sea outside, heard through the rock
surf: s("surf").slow(8).intensity(.5).occlude(.5).gain(.3)

// Water dripping from the roof at points around you, in a stone space
drips: s("drip*8?0.6").azimuth(rand.range(-180, 180)).elevation(rand.range(20, 70))
  .distance(rand.range(1, 3)).seed("cave").space("church").room(.5).gain(.16)

// The cave hum: 0 degrees centred, 90 looser, 180 diffuse and nearly gone in mono
hum: note("[a1,e2]").s("triangle").iphase("<0 90 180 90>")
  .attack(2).sustain(1).release(2).gain(.22)

// Bells of light from the entrance: earsh raises the right ear and lowers the left by 6 cents each
light: note("<e5 ~ b4 ~ c5 ~ a4 ~>").s("sine").fm(2).fmh(2.76).earsh(12)
  .decay(3).sustain(0).release(3).space("church").gain(.1)

setcpm(60/4)

// The spring bubbling up nearby, a breeze and a bird in the trees
spring: s("stream").slow(4).azimuth(-30).distance(2).gain(.2)
breeze: s("wind").slow(8).intensity(.15).gain(.06)
bird: s("bird").slow(4).azimuth(60).elevation(20).distance(6).gain(.16)

// Splashes: the same noise in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear a faint tune in the water
tune: s("[~ white]*4").dichotic("<[392 440 494 587] [523 494 440 392] [330 392 440 494] [440 392 330 294]>")
  .dichoticq(30).attack(.01).sustain(1).release(.08).gain(.12)

// A quiet hint: the first phrase on a sine, once every four bars
hint: note("<[~ g4 ~ a4 ~ b4 ~ d5] ~ ~ ~>").s("sine")
  .decay(.3).sustain(.2).release(.2).gain(.08)

// A soft pad holding the key: G, C, Em, D
pad: note("<[g2,d3,b3] [c3,g3,e4] [e2,b2,g3] [d3,a3,f#4]>")
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2)
  .lpf(1000).room(.6).gain(.14)
